  let quickCmdTab='info';
  function renderQuickCommands(){const tabs=$('quick-cmd-tabs'),list=$('quick-cmd-list'),search=$('quick-cmd-search');if(!tabs||!list)return;const keyword=(search?.value||'').trim().toLowerCase();tabs.replaceChildren();for(const cat of quickCommands){const b=document.createElement('button');b.textContent=cat.label;b.classList.toggle('active',!keyword&&cat.key===quickCmdTab);b.onclick=()=>{quickCmdTab=cat.key;if(search)search.value='';renderQuickCommands();};tabs.appendChild(b);}let items=[];if(keyword){for(const cat of quickCommands)for(const item of cat.items)if(item.n.toLowerCase().includes(keyword)||item.c.toLowerCase().includes(keyword))items.push(item);}else{const cat=quickCommands.find(c=>c.key===quickCmdTab)||quickCommands[0];items=cat.items;}list.replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='quick-cmd-empty';empty.textContent=keyword?'无匹配命令':'该分类暂无命令';list.appendChild(empty);return;}for(const item of items){const b=document.createElement('button');b.className='btn secondary quick-cmd-btn';b.dataset.device='';b.disabled=!driver?.connected;b.title=(item.d?item.d+'\n':'')+item.c;const name=document.createElement('span');name.className='qname';name.textContent=item.n;const cmd=document.createElement('span');cmd.className='qcmd';cmd.textContent=item.c;b.append(name,cmd);b.onclick=()=>perform(()=>runQuickCommand(item),b);b.oncontextmenu=event=>{event.preventDefault();navigator.clipboard.writeText(item.c).then(()=>toast('已复制命令：'+item.c),()=>toast('复制失败',true));};list.appendChild(b);}}
  async function runQuickCommand(item){if(!driver?.connected)throw new Error('请先连接设备');let cmd=item.c;if(item.p){for(const param of item.p){const val=await promptValue('常用命令',param.l,param.d||'');if(val===null)return;cmd=cmd.replaceAll('{'+param.k+'}',String(val).trim());}}await terminalView.open(driver);terminalView.send(cmd);terminalView.focus();}
